const defaultCoaches={homework:'Maya',gaming:'Byte',sports:'Kai'};
function coachPrefs(){return {...defaultCoaches,...JSON.parse(localStorage.getItem('nextmoveCoachPrefs')||'{}')}}
function saveCoachPrefs(prefs){localStorage.setItem('nextmoveCoachPrefs',JSON.stringify(prefs))}
function selectCoach(view,name,{persist=false}={}){const profile=coachProfiles[name],m=modes[view];if(!profile||!m)return;m.coach=name;m.badge=profile.badge;m.copy2=profile.description;m.copy=view==='homework'?`Add a clear image or PDF. ${name} will guide the next step without giving away the answer.`:view==='gaming'?`Share a clip up to 30 seconds and tell ${name} what game you are playing.`:`Share up to 30 seconds of game or practice footage for ${name} to review.`;if(persist){const prefs=coachPrefs();prefs[view]=name;saveCoachPrefs(prefs);syncCoachCards()}}
function applySavedCoach(view){selectCoach(view,coachPrefs()[view]||defaultCoaches[view])}
function syncCoachCards(){$$('[data-coach]').forEach(card=>{const selected=coachPrefs()[card.dataset.view]===card.dataset.coach;card.classList.toggle('selected-coach',selected);card.querySelector('.coach-selected')?.remove();if(selected)card.insertAdjacentHTML('beforeend','<span class="coach-selected">Your coach</span>')})}
function applyCoachQuiz(){const prefs={homework:$('#quizHomework')?.value||'Maya',gaming:$('#quizGaming')?.value||'Byte',sports:$('#quizSports')?.value||'Kai'};saveCoachPrefs(prefs);Object.entries(prefs).forEach(([view,name])=>selectCoach(view,name));syncCoachCards();const result=$('#coachQuizResult');if(result)result.textContent=`Saved: ${prefs.homework} for Homework, ${prefs.gaming} for Gaming, and ${prefs.sports} for Sports.`}
let mode='homework',file=null,currentUser=null,authMode='signup',activeView='dashboard',currentReportId=null;
function canUseCoaching(){return currentUser&&currentUser.age>=13}
function consentMessage(){return currentUser?.age<13?'NextMove is available only for learners age 13 and older in this public MVP.':'This account is not ready for coaching.'}
function under13Blocked(){return sessionStorage.getItem('nextmoveUnder13Blocked')==='true'}
const rewardState=()=>JSON.parse(localStorage.getItem('nextmoveRewards')||'{"coins":0,"claimed":[]}');
function saveRewards(state){localStorage.setItem('nextmoveRewards',JSON.stringify(state));updateCoins()}
function addCoinEvent(state,label,amount){state.history=Array.isArray(state.history)?state.history:[];state.history.unshift({label,amount,at:new Date().toISOString()});state.history=state.history.slice(0,100)}
function renderCoinHistory(){const box=$('#coinHistoryList');if(!box)return;const history=rewardState().history||[];box.innerHTML=history.length?history.map(item=>`<div class="coin-history-item ${item.amount>=0?'earn':'spend'}"><b>${item.amount>=0?'+':''}${item.amount} coins</b><span>${escapeHtml(item.label)}</span><small>${new Date(item.at).toLocaleDateString([], {month:'short',day:'numeric'})}</small></div>`).join(''):'<p class="empty small-empty">No coin activity yet. Complete a review to start earning.</p>'}
function weekStart(d=new Date()){const day=d.getDay(),start=new Date(d);start.setHours(0,0,0,0);start.setDate(start.getDate()-day);return start}
function weeklyCoinEvents(){const start=weekStart();return (rewardState().history||[]).filter(item=>new Date(item.at)>=start)}
function seededDailyGoals(){const start=weekStart(),weekKey=start.toISOString().slice(0,10),seed=[...weekKey].reduce((n,c)=>n+c.charCodeAt(0),0),pool=[
  {title:'Complete 5 coaching reviews',target:5,view:'homework',cta:'Start review',measure:e=>e.filter(x=>x.amount>0).length},
  {title:'Earn 25 coins from reviews',target:25,view:'homework',cta:'Earn coins',measure:e=>e.filter(x=>x.amount>0).reduce((sum,x)=>sum+x.amount,0)},
  {title:'Play 5 challenge rounds',target:5,view:'games',cta:'Play games',measure:e=>e.filter(x=>x.amount<0).length},
  {title:'Spend 100 coins on practice',target:100,view:'games',cta:'Practice',measure:e=>Math.abs(e.filter(x=>x.amount<0).reduce((sum,x)=>sum+x.amount,0))},
  {title:'Complete 2 sports reviews',target:2,view:'sports',cta:'Go sports',measure:e=>e.filter(x=>x.label.includes('Sports review')).length},
  {title:'Complete 2 homework reviews',target:2,view:'homework',cta:'Go homework',measure:e=>e.filter(x=>x.label.includes('Homework review')).length},
  {title:'Complete 2 gaming reviews',target:2,view:'gaming',cta:'Go gaming',measure:e=>e.filter(x=>x.label.includes('Gaming review')).length},
  {title:'Play 3 different games',target:3,view:'games',cta:'Choose game',measure:e=>new Set(e.filter(x=>x.amount<0).map(x=>x.label.replace(' replay',''))).size}
];return pool.map((goal,i)=>({goal,rank:(seed*(i+3)+i*17)%97})).sort((a,b)=>a.rank-b.rank).slice(0,5).map(x=>x.goal)}
function renderDailyGoal(){const list=$('#dailyGoalList'),score=$('#dailyGoalScore'),scoreShell=$('#dailyGoalScoreShell');if(!list)return;const events=weeklyCoinEvents(),goals=seededDailyGoals();let total=0;list.innerHTML=goals.map(goal=>{const value=goal.measure(events),pct=Math.min(100,Math.round((value/goal.target)*100));total+=pct;const tone=pct>=100?'green':pct>=50?'yellow':'red';return `<article class="daily-goal-item ${tone}"><div><b>${escapeHtml(goal.title)}</b><small>${Math.min(value,goal.target)} / ${goal.target}</small></div><span>${pct}%</span><div class="goal-progress"><i style="width:${pct}%"></i></div><button class="goal-go" data-goal-view="${escapeHtml(goal.view)}">${escapeHtml(goal.cta||'Go')} →</button></article>`}).join('');$$('[data-goal-view]').forEach(button=>button.onclick=()=>showView(button.dataset.goalView));const avg=Math.round(total/goals.length);if(score)score.textContent=`${avg}%`;if(scoreShell)scoreShell.className=`daily-score ${avg>=100?'green':avg>=50?'yellow':'red'}`}
function applyLocalTestCoins(){const params=new URLSearchParams(location.search),amount=Number(params.get('devCoins'));if(location.hostname!=='localhost'||!Number.isFinite(amount))return;const state=rewardState();state.coins=Math.max(0,Math.floor(amount));if(!Array.isArray(state.claimed))state.claimed=[];delete state.unlocked;localStorage.setItem('nextmoveRewards',JSON.stringify(state));params.delete('devCoins');history.replaceState(null,'',`${location.pathname}${params.toString()?`?${params}`:''}${location.hash}`)}
applyLocalTestCoins();
function updateCoins(){const coins=rewardState().coins||0;$('#coinCount').textContent=coins;$('#zoneCoinCount').textContent=coins;const play=$('#playPenalty');if(play){play.disabled=coins<20;play.textContent=coins>=20?'Play for 20 coins →':`Need ${20-coins} more coins`}}
async function request(url,options={}){let r;try{r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}})}catch{throw new Error('The server could not be reached. Please check your connection and try again.')}const d=await r.json().catch(()=>({error:'Unexpected server response'}));if(!r.ok)throw new Error(d.error||'Request failed');return d}
const pageTitles={dashboard:['WELCOME BACK','Dashboard'],homework:['COACHING STUDIO','Homework Tutor'],gaming:['COACHING STUDIO','Gaming Coach'],sports:['COACHING STUDIO','Sports Coach'],coaches:['YOUR COACH SQUAD','Meet the Coaches'],games:['LEARN · EARN · PLAY','Games & Coins'],reports:['SAVED FEEDBACK','Reports'],account:['PROFILE & SAFETY','Account'],report:['YOUR COACHING REPORT','Report']};
function closeMobileMenu(){$('#sidebar').classList.remove('open');$('#mobileScrim').classList.add('hidden')}
function showView(view){if(typeof stopCoachVoice==='function')stopCoachVoice();activeView=view;closeMobileMenu();$$('.side-link').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$$('.view').forEach(x=>x.classList.remove('active'));$('#report').classList.add('hidden');if(['homework','gaming','sports'].includes(view)){applySavedCoach(view);setMode(view);$('#coachView').classList.add('active')}else if(view==='coaches'){syncCoachCards();$('#coachesView').classList.add('active')}else if(view==='games'){$('#gamesView').classList.add('active')}else if(view==='reports'){$('#reportsView').classList.add('active');loadReportsPage()}else if(view==='account'){$('#accountView').classList.add('active');updateAccount()}else{$('#dashboardView').classList.add('active')}const [k,t]=pageTitles[view]||pageTitles.dashboard;$('#pageKicker').textContent=k;$('#pageTitle').textContent=t;window.scrollTo({top:0,behavior:'smooth'})}
function setMode(next){mode=next;const m=modes[next];$('#coachHeading').textContent=`${m.coach} · ${m.label}`;$('#coachLead').textContent=next==='homework'?'Get guided hints that build understanding without giving away the final answer.':next==='gaming'?'Upload a short clip and get practical advice on decisions, positioning, and repeatable improvement.':'Upload a short clip and get sport- and position-specific coaching from visible moments.';$('#coachBadge').textContent=m.badge;$('#formTitle').textContent=m.title;$('#formCopy').textContent=m.copy;$('#fileInput').accept=m.accept;$('#dropTitle').textContent=m.drop;$('#dropHelp').textContent=m.help;$('#notesLabel').textContent=m.notes;$('#fields').innerHTML=m.fields;$('#promiseQuote').textContent=m.quote;$('#promiseCopy').textContent=m.copy2;$('#promiseList').innerHTML=m.list.map(x=>`<li>${x}</li>`).join('');$('#faceOption').classList.toggle('hidden',next!=='sports');resetFile();$('#formError').textContent=''}
document.addEventListener('click',e=>{const target=e.target.closest('[data-view]');if(!target)return;const view=target.dataset.view;if(!view)return;e.preventDefault();if(target.dataset.coach)selectCoach(view,target.dataset.coach,{persist:true});showView(view)});
const baseSetModeForSafety=setMode;setMode=function(next){baseSetModeForSafety(next);$('#uploadDisclosure').textContent=next==='sports'?'Uploads are sent to an AI provider for coaching. Upload only what is needed, avoid private details and unnecessary bystanders, and remember sports feedback is not medical advice. Stop and ask a qualified adult or professional if something hurts.':'Uploads are sent to an AI provider to create coaching feedback. Upload only what is needed and do not include private, sensitive, or unnecessary personal information.'};
$('#menuBtn').onclick=()=>{$('#sidebar').classList.add('open');$('#mobileScrim').classList.remove('hidden')};$('#mobileScrim').onclick=closeMobileMenu;
const dz=$('#dropzone');['dragenter','dragover'].forEach(e=>dz.addEventListener(e,x=>{x.preventDefault();dz.classList.add('drag')}));['dragleave','drop'].forEach(e=>dz.addEventListener(e,x=>{x.preventDefault();dz.classList.remove('drag')}));dz.ondrop=e=>selectFile(e.dataTransfer.files[0]);$('#fileInput').onchange=e=>selectFile(e.target.files[0]);
async function selectFile(f){if(!f)return;$('#formError').textContent='';if(mode==='homework'){if(!['application/pdf','image/jpeg','image/png','image/webp'].includes(f.type))return $('#formError').textContent='Choose a JPG, PNG, WebP, or PDF homework file.';if(f.size>20*1024*1024)return $('#formError').textContent='Homework files must be 20 MB or smaller.'}if(mode!=='homework'){if(!f.type.startsWith('video/'))return $('#formError').textContent='Please choose a video clip.';if(f.size>100*1024*1024)return $('#formError').textContent='Video clips must be 100 MB or smaller.';try{const d=await videoDuration(f);if(!Number.isFinite(d)||d<=0)return $('#formError').textContent='This video does not have a readable duration.';if(d>30.5)return $('#formError').textContent='Please trim the clip to 30 seconds or less.'}catch{return $('#formError').textContent='This video format could not be read.'}}file=f;$('#dropEmpty').classList.add('hidden');$('#fileCard').classList.remove('hidden');$('#fileName').textContent=f.name;$('#fileMeta').textContent=`${(f.size/1024/1024).toFixed(1)} MB`}
function resetFile(){file=null;$('#fileInput').value='';$('#dropEmpty').classList.remove('hidden');$('#fileCard').classList.add('hidden')}$('#removeFile').onclick=e=>{e.preventDefault();resetFile()};
function videoDuration(f){return new Promise((ok,bad)=>{const v=document.createElement('video');v.preload='metadata';v.onloadedmetadata=()=>{URL.revokeObjectURL(v.src);ok(v.duration)};v.onerror=bad;v.src=URL.createObjectURL(f)})}
function toDataUrl(f){return new Promise((ok,bad)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=bad;r.readAsDataURL(f)})}
async function framesFromVideo(f,count=10){const url=URL.createObjectURL(f),v=document.createElement('video');v.muted=true;v.src=url;v.preload='auto';await new Promise((ok,bad)=>{v.onloadedmetadata=ok;v.onerror=bad});const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),duration=v.duration,frames=[];canvas.width=Math.min(v.videoWidth,960);canvas.height=Math.round(canvas.width*v.videoHeight/v.videoWidth);for(let i=0;i<count;i++){const sec=Math.min(duration-.05,(duration*i)/(count-1));v.currentTime=Math.max(0,sec);await new Promise(ok=>v.onseeked=ok);ctx.drawImage(v,0,0,canvas.width,canvas.height);frames.push({time:`0:${String(Math.round(sec)).padStart(2,'0')}`,data:canvas.toDataURL('image/jpeg',.72)})}URL.revokeObjectURL(url);return frames}
function meta(){return {coach:modes[mode].coach,notes:$('#notes').value.trim(),subject:$('#subject')?.value,level:$('#level')?.value,game:$('#game')?.value.trim(),role:$('#role')?.value.trim(),sport:$('#sport')?.value.trim(),position:$('#position')?.value.trim(),hasJersey:!!$('#hasJersey')?.checked,jersey:$('#jersey')?.value.trim(),hasJerseyName:!!$('#hasJerseyName')?.checked,jerseyName:$('#jerseyName')?.value.trim()}}
$('#analyzeBtn').onclick=async()=>{const err=$('#formError'),btn=$('#analyzeBtn');err.textContent='';if(!currentUser){openAuth('signup');return}if(!canUseCoaching()){err.textContent=consentMessage();return}if(!file){err.textContent='Choose a file first.';return}const m=meta();if(mode==='gaming'&&!m.game){err.textContent='Add the game name.';return}if(mode==='sports'&&(!m.sport||!m.position)){err.textContent='Add the sport and position.';return}if(mode==='sports'&&m.hasJersey&&!m.jersey){err.textContent='Add your jersey number, or uncheck “I have a jersey number.”';return}if(mode==='sports'&&m.hasJerseyName&&!m.jerseyName){err.textContent='Add your jersey name, or uncheck “I have a jersey name.”';return}btn.disabled=true;btn.textContent=mode==='homework'?'Reading your homework…':'Sampling and reviewing your clip…';try{let payload={mode,meta:m};if(mode==='homework')payload.file={name:file.name,kind:file.type==='application/pdf'?'pdf':'image',data:await toDataUrl(file)};else payload.frames=await framesFromVideo(file);const d=await request('/api/analyze',{method:'POST',body:JSON.stringify(payload)});renderReport(d.report)}catch(e){err.textContent=e.message}finally{btn.disabled=false;btn.textContent='Analyze my upload →'}};
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function formatText(s=''){return escapeHtml(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')}
let coachVoiceOn=false;
const coachVoiceProfiles={Maya:{rate:.92,pitch:1.15},Orion:{rate:.88,pitch:.92},Sol:{rate:.9,pitch:1.05},Quinn:{rate:.96,pitch:1},Byte:{rate:1.04,pitch:.9},Drift:{rate:1.08,pitch:.86},Nova:{rate:.94,pitch:.98},Echo:{rate:1,pitch:1.08},Kai:{rate:.94,pitch:.88},Riley:{rate:1,pitch:1.02},Ace:{rate:1.07,pitch:.93},Scout:{rate:.9,pitch:.96}};
function cleanSpeechText(s=''){return String(s).replace(/<[^>]+>/g,' ').replace(/\*\*([^*]+)\*\*/g,'$1').replace(/[â€¢Â·]/g,'. ').replace(/\s+/g,' ').trim()}
function pickCoachVoice(coach=''){const synth=window.speechSynthesis;if(!synth)return null;const voices=synth.getVoices().filter(v=>/^en/i.test(v.lang||''));if(!voices.length)return null;const index=[...coach].reduce((n,c)=>n+c.charCodeAt(0),0)%voices.length;return voices[index]}
function coachSpeechText(saved,page){const coach=saved?.report?.coach||saved?.meta?.coach||modes[saved?.mode]?.coach||'Your coach',parts=[`${coach} says.`,page.kicker,page.title,page.kind];if(page.items)parts.push(page.items.join('. '));else parts.push(page.body);return cleanSpeechText(parts.filter(Boolean).join('. '))}
function speakCoachPage(saved,page){if(!coachVoiceOn||!('speechSynthesis'in window))return;const synth=window.speechSynthesis;synth.cancel();const coach=saved?.report?.coach||saved?.meta?.coach||modes[saved?.mode]?.coach||'Maya',profile=coachVoiceProfiles[coach]||{rate:.95,pitch:1},utterance=new SpeechSynthesisUtterance(coachSpeechText(saved,page));utterance.rate=profile.rate;utterance.pitch=profile.pitch;utterance.voice=pickCoachVoice(coach);synth.speak(utterance)}
function updateVoiceUi(coach='Coach'){const toggle=$('#voiceToggle'),stop=$('#voiceStop'),status=$('#voiceStatus');if(toggle)toggle.textContent=coachVoiceOn?'🔊 Voice on':'🔊 Read aloud';if(stop)stop.classList.toggle('hidden',!coachVoiceOn);if(status)status.textContent=coachVoiceOn?`${coach} is reading this page`:'Coach voice off'}
function stopCoachVoice(){coachVoiceOn=false;if('speechSynthesis'in window)window.speechSynthesis.cancel();updateVoiceUi()}
function renderReport(saved){const r=saved.report;$$('.view').forEach(x=>x.classList.remove('active'));$('#report').classList.remove('hidden');$('#report').classList.add('active');$('#pageKicker').textContent='YOUR COACHING REPORT';$('#pageTitle').textContent='Report';$('#reportTitle').textContent=r.title;$('#reportSummary').textContent=r.summary;let cards=[];(r.observations||[]).forEach((o,i)=>cards.push(`<article class="report-card"><small>${escapeHtml(o.timestamp||`STEP ${i+1}`)} · OBSERVATION</small><h3>${escapeHtml(o.label)}</h3><p>${escapeHtml(o.detail)}</p></article>`));if(r.strengths?.length)cards.push(`<article class="report-card"><small>KEEP DOING</small><h3>Your strengths</h3><ul>${r.strengths.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul></article>`);if(r.improvements?.length)cards.push(`<article class="report-card"><small>WORK ON</small><h3>Improvements</h3><ul>${r.improvements.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul></article>`);if(r.drill)cards.push(`<article class="report-card"><small>PRACTICE</small><h3>Focused drill</h3><p>${escapeHtml(r.drill)}</p></article>`);$('#reportGrid').innerHTML=cards.slice(0,6).join('');$('#nextFocus').textContent=r.nextFocus||r.nextStep||r.question||'Choose one observation and practice it deliberately.';window.scrollTo({top:0,behavior:'smooth'})}
function reportPages(saved){const r=saved.report,mode=saved.mode,pages=[];(r.observations||[]).forEach((o,i)=>pages.push({kicker:mode==='homework'?`STEP ${i+1}`:`OBSERVATION ${o.timestamp||i+1}`,title:o.label||`${mode==='homework'?'Step':'Observation'} ${i+1}`,body:o.detail||'',kind:mode==='homework'?'Guided step':'What the coach noticed'}));if(r.strengths?.length)pages.push({kicker:'KEEP DOING',title:'Your strengths',items:r.strengths,kind:'Positive pattern'});const improvements=[...(r.improvements||[])];if(mode!=='homework'&&!improvements.length){if(r.nextFocus)improvements.push(r.nextFocus);else if(r.drill)improvements.push(r.drill)}improvements.forEach((item,i)=>pages.push({kicker:`IMPROVEMENT ${i+1}`,title:mode==='sports'?'How to improve this play':mode==='gaming'?'How to improve next round':'What to work on',body:item,kind:'Actionable improvement'}));if(r.drill)pages.push({kicker:'PRACTICE',title:'Focused drill',body:r.drill,kind:'Training'});if(r.question&&mode==='homework')pages.push({kicker:'CHECK YOUR UNDERSTANDING',title:'Try this before moving on',body:r.question,kind:'Quick check'});return pages.length?pages:[{kicker:'NEXT MOVE',title:'Start here',body:r.nextFocus||r.nextStep||'Choose one thing to practice deliberately.',kind:'Focus'}]}
