let questions=[],questionIndex=0,shotScore=0,pendingCorrect=false,shotLocked=false,shotCurve='straight';
function shuffled(items){const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function makeQuestions(){
  const builders=[
    ()=>{const a=2+Math.floor(Math.random()*11),b=2+Math.floor(Math.random()*11);return{text:`${a} × ${b} = ?`,answer:a*b}},
    ()=>{const answer=4+Math.floor(Math.random()*25),b=2+Math.floor(Math.random()*18);return{text:`${answer+b} − ${b} = ?`,answer}},
    ()=>{const a=5+Math.floor(Math.random()*35),b=3+Math.floor(Math.random()*25);return{text:`${a} + ${b} = ?`,answer:a+b}},
    ()=>{const answer=2+Math.floor(Math.random()*10),divisor=2+Math.floor(Math.random()*9);return{text:`${answer*divisor} ÷ ${divisor} = ?`,answer}}
  ];
  return shuffled(builders).slice(0,3).map(build=>build());
}
function showQuestion(){$('#questionNumber').textContent=questionIndex+1;$('#mathQuestion').textContent=questions[questionIndex].text;$('#mathAnswer').value='';$('#mathAnswer').disabled=false;$('#checkAnswer').disabled=false;$('#gameFeedback').textContent='Solve it, then choose your shot.';$('#gameBall').className='game-ball';$('#keeper').className='keeper';$('#penaltyPlayer').className='penalty-player';shotCurve='straight';$$('#curvePanel button').forEach(b=>b.classList.toggle('active',b.dataset.curve==='straight'));$('#curvePanel').classList.add('hidden');$('#aimControls').classList.add('hidden');shotLocked=false;setTimeout(()=>$('#mathAnswer').focus(),50)}
function startPenalty(){questions=makeQuestions();questionIndex=0;shotScore=0;$('#shotScore').textContent='0';$('#questionBox').classList.remove('hidden');$('#gameFinish').classList.add('hidden');showQuestion();if(!$('#penaltyDialog').open)$('#penaltyDialog').showModal()}
$('#playPenalty').onclick=startPenalty;$('#playAgain').onclick=startPenalty;$('#closePenalty').onclick=()=>$('#penaltyDialog').close();
$('#answerForm').onsubmit=e=>{e.preventDefault();if(shotLocked)return;const raw=$('#mathAnswer').value;if(raw.trim()==='')return;pendingCorrect=Number(raw)===questions[questionIndex].answer;$('#mathAnswer').disabled=true;$('#checkAnswer').disabled=true;$('#aimControls').classList.remove('hidden');$('#gameFeedback').textContent=pendingCorrect?'Correct! Now pick a corner and shoot.':'Now take your shot—then we’ll show the answer.'};
$$('#aimControls button').forEach(button=>button.onclick=()=>{if(shotLocked)return;shotLocked=true;const aim=button.dataset.aim,keeperAim=['left','center','right'][Math.floor(Math.random()*3)];$('#aimControls').classList.add('hidden');$('#keeper').classList.add(`dive-${keeperAim}`);$('#gameBall').classList.add(pendingCorrect?`goal-${aim}`:`miss-${aim}`);if(pendingCorrect){shotScore++;$('#shotScore').textContent=shotScore;$('#gameFeedback').textContent='GOAL! Your shot finished inside the net.'}else $('#gameFeedback').textContent=`Just wide. The answer was ${questions[questionIndex].answer}.`;setTimeout(()=>{questionIndex++;if(questionIndex<3)showQuestion();else{$('#questionBox').classList.add('hidden');$('#gameFinish').classList.remove('hidden');$('#finishCopy').textContent=`You scored ${shotScore} of 3. Every attempt trains your brain for the next one.`}},950)});
updateCoins();

// Free-aim shootout: answer first, then place the shot anywhere in the goal.
$('#answerForm').onsubmit=e=>{e.preventDefault();if(shotLocked)return;const raw=$('#mathAnswer').value;if(raw.trim()==='')return;pendingCorrect=Number(raw)===questions[questionIndex].answer;$('#mathAnswer').disabled=true;$('#checkAnswer').disabled=true;$('#curvePanel').classList.remove('hidden');$('#aimControls').classList.remove('hidden');$('#aimControls span').textContent='Choose curve, then tap the goal to shoot';$('#gameFeedback').textContent=pendingCorrect?'Correct! Choose a curve, then tap the goal to shoot.':'Choose a curve and tap the goal—then we’ll review the answer.'};
$$('#curvePanel button').forEach(button=>button.onclick=()=>{shotCurve=button.dataset.curve;$$('#curvePanel button').forEach(b=>b.classList.toggle('active',b===button));$('#gameFeedback').textContent=`${button.textContent} selected. Now aim your shot.`});
function takeReactiveShot(e){if(shotLocked||$('#aimControls').classList.contains('hidden'))return;shotLocked=true;const field=$('.stadium'),fieldRect=field.getBoundingClientRect(),goalRect=$('.goal').getBoundingClientRect(),ballRect=$('#gameBall').getBoundingClientRect(),keeperRect=$('#keeper').getBoundingClientRect();const rawPoint=e.type==='keydown'||!Number.isFinite(e.clientX)||!Number.isFinite(e.clientY)?{x:goalRect.left+goalRect.width/2,y:goalRect.top+goalRect.height/2}:{x:e.clientX,y:e.clientY};const point={x:Math.max(fieldRect.left,Math.min(fieldRect.right,rawPoint.x)),y:Math.max(fieldRect.top,Math.min(fieldRect.bottom,rawPoint.y))};const mouth={left:goalRect.left+16,right:goalRect.right-16,top:goalRect.top+18,bottom:goalRect.bottom-20};const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));const curveEffect={left:-38,right:38,top:0,straight:0}[shotCurve]||0,curveDip=shotCurve==='top'?24:0;const finalPoint={x:point.x+curveEffect,y:point.y+curveDip};const finalInGoal=finalPoint.x>=mouth.left&&finalPoint.x<=mouth.right&&finalPoint.y>=mouth.top&&finalPoint.y<=mouth.bottom;const reactionError={x:(Math.random()-.5)*170,y:(Math.random()-.5)*110};const keeperPoint={x:clamp(finalPoint.x+reactionError.x,mouth.left,mouth.right),y:clamp(finalPoint.y+reactionError.y,mouth.top,mouth.bottom)};const saved=finalInGoal&&Math.hypot(finalPoint.x-keeperPoint.x,finalPoint.y-keeperPoint.y)<30;$('#aimControls').classList.add('hidden');$('#curvePanel').classList.add('hidden');const ball=$('#gameBall'),keeper=$('#keeper'),player=$('#penaltyPlayer');player.className='penalty-player run-kick';ball.style.setProperty('--shot-x',`${finalPoint.x-(ballRect.left+ballRect.width/2)}px`);ball.style.setProperty('--shot-y',`${finalPoint.y-(ballRect.top+ballRect.height/2)}px`);ball.style.setProperty('--curve-mid-x',`${curveEffect*-1.35}px`);ball.style.setProperty('--curve-mid-y',`${shotCurve==='top'?-78:-42}px`);keeper.style.setProperty('--keeper-x',`${keeperPoint.x-(keeperRect.left+keeperRect.width/2)}px`);keeper.style.setProperty('--keeper-y',`${keeperPoint.y-(keeperRect.top+keeperRect.height/2)}px`);setTimeout(()=>{ball.classList.add(saved?'shot-saved':'user-shot');keeper.classList.add('free-dive');if(!finalInGoal)$('#gameFeedback').textContent='MISS! The curve carried that shot outside the goal.';else if(saved)$('#gameFeedback').textContent='SAVED! The goalkeeper touched the shot.';else if(!pendingCorrect)$('#gameFeedback').textContent=`Curved into the net, but the answer was ${questions[questionIndex].answer}, so it does not count.`;else{shotScore++;$('#shotScore').textContent=shotScore;$('#gameFeedback').textContent='GOAL! The curve beat the goalkeeper.'}},230);setTimeout(()=>{questionIndex++;if(questionIndex<3)showQuestion();else{$('#questionBox').classList.add('hidden');$('#gameFinish').classList.remove('hidden');$('#finishCopy').textContent=`You scored ${shotScore} of 3. Every attempt trains your brain for the next one.`}},1460)}
$('#aimControls').onclick=takeReactiveShot;$('#aimControls').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();takeReactiveShot(e)}};

// Economy: eligible coaching reviews earn coins and unlock games permanently.
const economyRenderReport=renderReport;
renderReport=function(saved){economyRenderReport(saved);const rewards={homework:5,sports:3,gaming:1},amount=rewards[saved.mode];if(!amount)return;const state=rewardState();if(state.claimed.includes(saved.id))return;state.claimed.push(saved.id);state.coins=(state.coins||0)+amount;addCoinEvent(state,`${saved.mode[0].toUpperCase()+saved.mode.slice(1)} review completed`,amount);saveRewards(state);$('#rewardClaim').dataset.ready='true';$('#rewardClaim').classList.add('hidden');$('#rewardHeading').textContent=`${amount} NextMove Coin${amount===1?'':'s'} earned`;$('#claimReward').disabled=true;$('#claimReward').textContent=`${amount} coin${amount===1?'':'s'} added!`};
updateCoins();

// Continue the conversation from any saved coaching report.
let activeChatReport=null,chatMessages=[];
function paintChat(){const box=$('#chatMessages');box.innerHTML='';chatMessages.forEach(message=>{const bubble=document.createElement('div');bubble.className=`chat-bubble ${message.role==='user'?'user':'coach'}`;bubble.innerHTML=formatText(message.content);box.appendChild(bubble)});box.scrollTop=box.scrollHeight}
function setupReportChat(saved){activeChatReport=saved;const coach=saved.coach||saved.report?.coach||modes[saved.mode]?.coach||'NextMove Coach',name=currentUser?.name||'there';$('#chatTitle').textContent=`Chat with ${coach}`;$('#chatCoachAvatar').textContent=saved.mode==='homework'?'📚':saved.mode==='gaming'?'🎧':'⚽';chatMessages=[{role:'assistant',content:`Hi ${name}—I’m ${coach}. I remember this coaching report. What would you like me to explain or help you practice next?`}];$('#chatError').textContent='';$('#chatInput').value='';paintChat()}
const chatRenderReport=renderReport;renderReport=function(saved){chatRenderReport(saved);setupReportChat(saved)};
$('#chatForm').onsubmit=async e=>{e.preventDefault();const input=$('#chatInput'),send=$('#chatSend'),question=input.value.trim();if(!question||!activeChatReport||send.disabled)return;chatMessages.push({role:'user',content:question});input.value='';paintChat();send.disabled=true;send.textContent='Thinking…';$('#chatError').textContent='';const thinking=document.createElement('div');thinking.className='chat-bubble coach thinking';thinking.textContent='Thinking about your question…';$('#chatMessages').appendChild(thinking);try{const coach=activeChatReport.coach||activeChatReport.report?.coach||modes[activeChatReport.mode]?.coach||'NextMove Coach';const data=await request('/api/chat',{method:'POST',body:JSON.stringify({reportId:activeChatReport.id,coach,messages:chatMessages})});thinking.remove();chatMessages.push({role:'assistant',content:data.reply});paintChat()}catch(error){thinking.remove();$('#chatError').textContent=error.message}finally{send.disabled=false;send.textContent='Send →';input.focus()}};

// Game entries cost coins each time, so practice stays earned instead of permanently unlocked.
updateCoins=function(){const state=rewardState(),coins=state.coins||0;delete state.unlocked;$('#coinCount').textContent=coins;$('#zoneCoinCount').textContent=coins;const sync=(selector,cost)=>{const button=$(selector);if(!button)return;if(coins>=cost){button.disabled=false;button.textContent=`Play for ${cost} coins →`}else{button.disabled=true;button.textContent=`Need ${cost-coins} more coins`}};sync('#playPenalty',20);sync('#playSpace',30);sync('#playCricket',35);renderCoinHistory();renderDailyGoal()};
function spendAndPlay(cost,start,label='Game played'){const state=rewardState();if((state.coins||0)<cost){showView('games');updateCoins();return}state.coins-=cost;addCoinEvent(state,label,-cost);saveRewards(state);start()}
$('#playPenalty').onclick=()=>spendAndPlay(20,startPenalty,'Penalty Shootout');$('#playAgain').onclick=()=>spendAndPlay(20,startPenalty,'Penalty Shootout replay');
const sciencePool=[{q:'Which force keeps planets moving around the Sun?',o:['Gravity','Sound','Friction','Magnetism'],a:0,e:'Gravity pulls planets toward the Sun while they move forward.'},{q:'What gas do humans need to breathe?',o:['Oxygen','Helium','Carbon dioxide','Hydrogen'],a:0,e:'Our bodies use oxygen during cellular respiration.'},{q:'Which state of matter has a fixed volume but takes the shape of its container?',o:['Liquid','Solid','Gas','Plasma'],a:0,e:'A liquid keeps its volume but changes shape.'},{q:'What happens to water at 0°C under normal conditions?',o:['It freezes','It boils','It disappears','It becomes salt'],a:0,e:'Water freezes into ice at about 0°C.'},{q:'Which organ pumps blood around the body?',o:['Heart','Lungs','Stomach','Brain'],a:0,e:'The heart pumps blood through the circulatory system.'},{q:'Why does the Moon appear bright?',o:['It reflects sunlight','It makes fire','It stores lightning','It glows from heat'],a:0,e:'The Moon reflects light from the Sun.'},{q:'Which particle has a negative electric charge?',o:['Electron','Proton','Neutron','Photon'],a:0,e:'Electrons carry negative charge.'},{q:'What process lets plants turn light energy into stored chemical energy?',o:['Photosynthesis','Respiration','Condensation','Erosion'],a:0,e:'Photosynthesis uses light, water, and carbon dioxide to make sugars.'},{q:'If an object moves at constant velocity, what is its net force?',o:['Zero','Increasing','Equal to its mass','Always downward'],a:0,e:'Constant velocity means no acceleration, so the net force is zero.'}];
let spaceQuestions=[],spaceIndex=0,spaceFuel=3,spaceCorrect=0;
function pickScience(){const age=currentUser?.age||14,limit=age<13?6:age<18?8:9;return shuffled(sciencePool.slice(0,limit)).slice(0,3).map(item=>{const choices=shuffled(item.o.map((text,index)=>({text,correct:index===item.a})));return {...item,o:choices.map(x=>x.text),a:choices.findIndex(x=>x.correct)}})}
function showSpaceQuestion(){const item=spaceQuestions[spaceIndex];$('#spaceNumber').textContent=spaceIndex+1;$('#spacePrompt').textContent=item.q;$('#spaceFeedback').textContent='';$('#spaceOptions').innerHTML='';item.o.forEach((option,index)=>{const button=document.createElement('button');button.type='button';button.textContent=option;button.onclick=()=>answerSpace(index);$('#spaceOptions').appendChild(button)})}
function answerSpace(choice){const item=spaceQuestions[spaceIndex],correct=choice===item.a;$$('#spaceOptions button').forEach(button=>button.disabled=true);if(correct){spaceCorrect++;$('#spaceShip').className=`space-ship step-${spaceCorrect}`;$('#spaceProgress').style.width=`${(spaceCorrect/spaceQuestions.length)*100}%`;$('#spaceFeedback').textContent=`Bucket! ${item.e}`}else{spaceFuel--;$('#spaceFuel').textContent='⏱ '.repeat(spaceFuel).trim()||'BUZZER';$('#asteroid').classList.remove('hidden');setTimeout(()=>$('#asteroid').classList.add('hidden'),800);$('#spaceFeedback').textContent=`Defender contest! ${item.e}`}setTimeout(()=>{spaceIndex++;if(spaceIndex<spaceQuestions.length)showSpaceQuestion();else finishSpace()},950)}
function finishSpace(){const success=spaceFuel>0&&spaceCorrect===spaceQuestions.length;$('#spaceQuestion').classList.add('hidden');$('#spaceFinish').classList.remove('hidden');$('#spaceFinishIcon').textContent=success?'🏀':'⏱️';$('#spaceFinishTitle').textContent=success?'Buzzer beater!':'Shot came up short';$('#spaceFinishCopy').textContent=success?`The ball dropped at the buzzer with ${spaceFuel} tick${spaceFuel===1?'':'s'} left.`:`You made ${spaceCorrect} of ${spaceQuestions.length} clutch reads. Run it back and finish the possession.`}
function startSpace(){spaceQuestions=pickScience();spaceIndex=0;spaceFuel=3;spaceCorrect=0;$('#spaceFuel').textContent='⏱ ⏱ ⏱';$('#spaceShip').className='space-ship';$('#spaceProgress').style.width='0';$('#spaceQuestion').classList.remove('hidden');$('#spaceFinish').classList.add('hidden');showSpaceQuestion();if(!$('#spaceDialog').open)$('#spaceDialog').showModal()}
$('#playSpace').onclick=()=>spendAndPlay(30,startSpace,'Basketball Clutch Shot');$('#spaceAgain').onclick=()=>spendAndPlay(30,startSpace,'Basketball replay');$('#closeSpace').onclick=()=>$('#spaceDialog').close();updateCoins();

const cricketPool=[{q:'The bowler sends a short ball rising toward your chest. What is the safest scoring shot?',o:['Pull it along the ground','Leave your bat hanging','Charge straight at it','Swing with eyes closed'],a:0,e:'A controlled pull keeps your eyes level and sends the ball into space.'},{q:'A full ball lands near your front foot. Which shot usually fits?',o:['Straight drive','Hook shot','Late cut','Duck under it'],a:0,e:'A full delivery is perfect for a balanced front-foot drive.'},{q:'The field has many players on the leg side. Where should you look for the gap?',o:['Off side','Straight to midwicket','At the keeper','Behind your own stumps'],a:0,e:'If one side is crowded, smart batters search the open side.'},{q:'The ball is wide outside off stump. What is the best decision?',o:['Let it go or cut if safe','Swing across the line','Run without hitting','Turn your back'],a:0,e:'Wide balls reward patience or a controlled cut, not a wild swipe.'},{q:'You need 4 runs from 1 ball. What matters most?',o:['Pick the gap before swinging','Hit as hard as possible only','Ignore the field','Run before contact'],a:0,e:'Reading the field gives power a direction.'},{q:'A slower ball arrives later than expected. What should you adjust?',o:['Wait longer before hitting','Swing earlier','Close your eyes','Step away from the crease'],a:0,e:'Timing beats rushing when the pace changes.'}];
let cricketQuestions=[],cricketIndex=0,cricketRuns=0;
function pickCricket(){return shuffled(cricketPool).slice(0,3).map(item=>{const choices=shuffled(item.o.map((text,index)=>({text,correct:index===item.a})));return {...item,o:choices.map(x=>x.text),a:choices.findIndex(x=>x.correct)}})}
function showCricketQuestion(){const item=cricketQuestions[cricketIndex];$('#cricketNumber').textContent=cricketIndex+1;$('#cricketOver').textContent=`0.${cricketIndex}`;$('#cricketPrompt').textContent=item.q;$('#cricketFeedback').textContent='Read the delivery, then pick your shot.';$('#cricketOptions').innerHTML='';$('#cricketPlayer').className='cricket-player';$('#cricketShotBall').className='cricket-shot-ball';$('#cricketBoundary').classList.remove('show');$('#cricketCrowd')?.classList.remove('celebrate');$('#nextmoveHit')?.classList.add('hidden');$('#nextmoveHit')?.classList.remove('six');item.o.forEach((option,index)=>{const button=document.createElement('button');button.type='button';button.textContent=option;button.onclick=()=>answerCricket(index);$('#cricketOptions').appendChild(button)})}
function answerCricket(choice){const item=cricketQuestions[cricketIndex],correct=choice===item.a;$$('#cricketOptions button').forEach(button=>button.disabled=true);$('#cricketPlayer').classList.add('swing');if(correct){const runs=Math.min(cricketIndex===2&&cricketRuns<=6?6:4,12-cricketRuns);cricketRuns+=runs;$('#cricketRuns').textContent=cricketRuns;$('#cricketShotBall').classList.add(runs===6?'six':'four');$('#cricketBoundary').textContent=runs===6?'SIX!':'FOUR!';$('#cricketBoundary').classList.add('show');$('#nextmoveHitNumber').textContent=runs;const hit=$('#nextmoveHit');hit?.classList.remove('hidden','six');if(runs===6)hit?.classList.add('six');const crowd=$('#cricketCrowd');crowd?.classList.remove('celebrate');void crowd?.offsetWidth;crowd?.classList.add('celebrate');$('#cricketFeedback').textContent=`${runs} runs! ${item.e}`}else{$('#cricketShotBall').classList.add('dot');$('#cricketFeedback').textContent=`Dot ball. ${item.e}`}setTimeout(()=>{cricketIndex++;if(cricketIndex<cricketQuestions.length&&cricketRuns<12)showCricketQuestion();else finishCricket()},1050)}
function finishCricket(){const success=cricketRuns>=12,ballsLeft=3-Math.min(cricketIndex,3);$('#cricketQuestion').classList.add('hidden');$('#cricketFinish').classList.remove('hidden');$('#cricketOver').textContent=`0.${Math.min(cricketIndex,3)}`;$('#cricketFinishIcon').textContent=success?'🏆':'🏏';$('#cricketFinishTitle').textContent=success?'Chase complete!':'Target defended';$('#cricketFinishCopy').textContent=success?`You chased 12 ${ballsLeft?`with ${ballsLeft} deliver${ballsLeft===1?'y':'ies'} left`:'on the final delivery'}. Smart shot selection wins.`:`You scored ${cricketRuns}/12. Read the field, wait for the right ball, and bat again.`}
function startCricket(){cricketQuestions=pickCricket();cricketIndex=0;cricketRuns=0;$('#cricketRuns').textContent='0';$('#cricketQuestion').classList.remove('hidden');$('#cricketFinish').classList.add('hidden');showCricketQuestion();if(!$('#cricketDialog').open)$('#cricketDialog').showModal()}
$('#playCricket').onclick=()=>spendAndPlay(35,startCricket,'Cricket Chase');$('#cricketAgain').onclick=()=>spendAndPlay(35,startCricket,'Cricket replay');$('#closeCricket').onclick=()=>$('#cricketDialog').close();updateCoins();

// Friends + party MVP for 13+ users. Accepted friends only; no public discovery.
let selectedFriendId=null,friendsCache=[],partyCache=null;
function installFriendsUi(){
  if(!document.querySelector('[data-view="friends"]'))document.querySelector('[data-view="reports"]').insertAdjacentHTML('beforebegin','<button class="side-link" data-view="friends"><i>●</i><span>Friends</span></button>');
  if(!$('#shareParty'))document.querySelector('#report .account-actions').insertAdjacentHTML('afterbegin','<button class="outline-btn" id="shareParty">Share to party</button>');
  if(!$('#friendsView'))$('#accountView').insertAdjacentHTML('beforebegin',`<section class="view" id="friendsView"><div class="section-title"><div><span class="kicker">FRIENDS & PARTY</span><h2>Learn together safely.</h2></div><p>Invite people you know, chat with accepted friends, and share selected coaching reports inside your party.</p></div><div class="friends-layout"><article class="account-card"><h3>Add a friend</h3><form class="friend-form" id="friendInviteForm"><input type="email" id="friendEmail" placeholder="friend@example.com" aria-label="Friend email"><button class="dark-btn">Invite</button></form><p class="form-error" id="friendsError"></p><div class="friend-columns"><div><h4>Requests</h4><div id="friendRequests" class="mini-list"></div></div><div><h4>Friends</h4><div id="friendsList" class="mini-list"></div></div></div></article><article class="account-card"><h3 id="friendChatTitle">Friend chat</h3><div class="chat-messages mini-chat" id="friendChatMessages"></div><form class="chat-form compact-chat" id="friendChatForm"><input id="friendChatInput" maxlength="1000" autocomplete="off" placeholder="Message a friend..." aria-label="Message a friend"><button class="dark-btn">Send</button></form></article><article class="account-card party-card"><h3>Party</h3><p>Invite accepted friends to your party. Shared reports are visible to party members.</p><div id="partyInvites" class="mini-list"></div><div id="partyMembers" class="mini-list"></div><label class="party-invite">Invite friend to party<select id="partyFriendSelect"></select><button class="outline-btn" id="partyInviteBtn">Invite</button></label><div class="chat-messages mini-chat" id="partyMessages"></div><form class="chat-form compact-chat" id="partyChatForm"><input id="partyChatInput" maxlength="1000" autocomplete="off" placeholder="Chat with your party..." aria-label="Chat with party"><button class="dark-btn">Send</button></form><h4>Shared reports</h4><div id="partyReports" class="mini-list"></div></article></div></section>`);
  if(!$('#friendsSafetyNote'))$('#friendsView .section-title').insertAdjacentHTML('afterend','<p class="friends-safety-note" id="friendsSafetyNote">Only add people you know. Do not share private details. You can remove friends, block them, leave a party, or report a message anytime.</p>');
  if(!$('#partyLeaveBtn'))$('#partyReports').insertAdjacentHTML('afterend','<button class="outline-btn party-leave" id="partyLeaveBtn">Leave party</button>');
  $('#friendInviteForm').onsubmit=async e=>{e.preventDefault();$('#friendsError').textContent='';try{await request('/api/friends/invite',{method:'POST',body:JSON.stringify({email:$('#friendEmail').value})});$('#friendEmail').value='';await loadFriendsHub()}catch(error){$('#friendsError').textContent=error.message}};
  $('#friendChatForm').onsubmit=async e=>{e.preventDefault();const text=$('#friendChatInput').value.trim();if(!selectedFriendId||!text)return;await request('/api/friends/chat',{method:'POST',body:JSON.stringify({friendId:selectedFriendId,text})});$('#friendChatInput').value='';await loadFriendChat()};
  $('#partyInviteBtn').onclick=async e=>{e.preventDefault();const friendId=$('#partyFriendSelect').value;if(!friendId)return;await request('/api/party/invite',{method:'POST',body:JSON.stringify({friendId})});await loadFriendsHub()};
  $('#partyChatForm').onsubmit=async e=>{e.preventDefault();const text=$('#partyChatInput').value.trim();if(!text)return;await request('/api/party/message',{method:'POST',body:JSON.stringify({text})});$('#partyChatInput').value='';await loadParty()};
  $('#partyLeaveBtn').onclick=async e=>{e.preventDefault();if(!confirm('Leave this party? Shared reports from this party will no longer be visible to you.'))return;await request('/api/party/leave',{method:'POST',body:'{}'});await loadFriendsHub()};
  $('#shareParty').onclick=async()=>{const reportId=currentReportId||activeChatReport?.id;if(!reportId)return alert('Open a saved report first.');try{await request('/api/party/share',{method:'POST',body:JSON.stringify({reportId})});alert('Shared to your party.');await loadParty()}catch(error){alert(error.message)}};
}
function friendRow(friend){return `<div class="history-item friend-row"><button class="friend-open" data-friend="${escapeHtml(friend.id)}"><b>${escapeHtml(friend.name)} ${friend.online?'●':''}</b><small>${escapeHtml(friend.email)}</small></button><div class="friend-actions"><button class="text-btn" data-remove-friend="${escapeHtml(friend.id)}">Remove</button><button class="text-btn danger" data-block-friend="${escapeHtml(friend.id)}">Block</button></div></div>`}
async function loadFriendsHub(){if(!currentUser){$('#friendsError').textContent='Sign in to use Friends.';return}try{const data=await request('/api/friends');friendsCache=data.friends||[];$('#friendRequests').innerHTML=[...(data.incoming||[]).map(r=>`<div class="mini-item"><b>${escapeHtml(r.from.name)}</b><small>wants to be friends</small><button class="outline-btn" data-accept="${escapeHtml(r.id)}">Accept</button><button class="text-btn" data-decline="${escapeHtml(r.id)}">Decline</button></div>`),...(data.outgoing||[]).map(r=>`<div class="mini-item"><b>${escapeHtml(r.to.name)}</b><small>invite pending</small></div>`)].join('')||'<p class="empty small-empty">No requests.</p>';$('#friendsList').innerHTML=friendsCache.map(friendRow).join('')||'<p class="empty small-empty">No friends yet.</p>';$$('[data-accept]').forEach(b=>b.onclick=async()=>{await request('/api/friends/respond',{method:'POST',body:JSON.stringify({requestId:b.dataset.accept,accept:true})});await loadFriendsHub()});$$('[data-decline]').forEach(b=>b.onclick=async()=>{await request('/api/friends/respond',{method:'POST',body:JSON.stringify({requestId:b.dataset.decline,accept:false})});await loadFriendsHub()});$$('[data-friend]').forEach(b=>b.onclick=async()=>{selectedFriendId=b.dataset.friend;await loadFriendChat()});$$('[data-remove-friend]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this friend? Your direct chat with them will be deleted.'))return;await request('/api/friends/remove',{method:'POST',body:JSON.stringify({friendId:b.dataset.removeFriend})});if(selectedFriendId===b.dataset.removeFriend)selectedFriendId=null;await loadFriendsHub()});$$('[data-block-friend]').forEach(b=>b.onclick=async()=>{if(!confirm('Block this friend? They will be removed and direct chat will be deleted.'))return;await request('/api/friends/block',{method:'POST',body:JSON.stringify({friendId:b.dataset.blockFriend})});if(selectedFriendId===b.dataset.blockFriend)selectedFriendId=null;await loadFriendsHub()});$('#partyInvites').innerHTML=(data.partyInvites||[]).map(invite=>`<div class="mini-item"><b>${escapeHtml(invite.from.name)} invited you to a party</b><button class="outline-btn" data-party-accept="${escapeHtml(invite.id)}">Join</button><button class="text-btn" data-party-decline="${escapeHtml(invite.id)}">Decline</button></div>`).join('');$$('[data-party-accept]').forEach(b=>b.onclick=async()=>{await request('/api/party/respond',{method:'POST',body:JSON.stringify({partyId:b.dataset.partyAccept,accept:true})});await loadFriendsHub()});$$('[data-party-decline]').forEach(b=>b.onclick=async()=>{await request('/api/party/respond',{method:'POST',body:JSON.stringify({partyId:b.dataset.partyDecline,accept:false})});await loadFriendsHub()});await loadParty();if(selectedFriendId)await loadFriendChat()}catch(error){$('#friendsError').textContent=error.message}}
async function reportSafety(kind,messageId,targetUserId){const reason=prompt('Optional: what should we know about this report?')||'User reported this content.';await request('/api/safety/report',{method:'POST',body:JSON.stringify({kind,messageId,targetUserId,reason})})}
async function loadFriendChat(){const friend=friendsCache.find(f=>f.id===selectedFriendId);$('#friendChatTitle').textContent=friend?`Chat with ${friend.name}`:'Friend chat';if(!friend){$('#friendChatMessages').innerHTML='<p class="empty small-empty">Choose a friend to chat.</p>';return}const data=await request(`/api/friends/chat?friendId=${encodeURIComponent(friend.id)}`);$('#friendChatMessages').innerHTML=(data.messages||[]).map(m=>`<div class="chat-bubble ${m.from===currentUser.id?'user':'coach'}">${formatText(m.text)}<button class="report-message" data-report-friend="${escapeHtml(m.id)}" data-target="${escapeHtml(friend.id)}">Report</button></div>`).join('')||'<p class="empty small-empty">No messages yet.</p>';$$('[data-report-friend]').forEach(b=>b.onclick=async()=>{await reportSafety('friend-message',b.dataset.reportFriend,b.dataset.target);await loadFriendChat()});$('#friendChatMessages').scrollTop=$('#friendChatMessages').scrollHeight}
async function loadParty(){const data=await request('/api/party');partyCache=data.party;$('#partyMembers').innerHTML=(partyCache.members||[]).map(m=>`<div class="mini-item"><b>${escapeHtml(m.name)} ${m.online?'●':''}</b><small>${escapeHtml(m.email)}</small></div>`).join('');const inviteOptions=friendsCache.filter(f=>!(partyCache.members||[]).some(m=>m.id===f.id));$('#partyFriendSelect').innerHTML=`<option value="">${inviteOptions.length?'Choose friend':'No accepted friends to invite yet'}</option>`+inviteOptions.map(f=>`<option value="${escapeHtml(f.id)}">${escapeHtml(f.name)}</option>`).join('');$('#partyFriendSelect').disabled=!inviteOptions.length;$('#partyInviteBtn').disabled=!inviteOptions.length;$('#partyMessages').innerHTML=(partyCache.messages||[]).map(m=>`<div class="chat-bubble ${m.from===currentUser.id?'user':'coach'}"><b>${escapeHtml(m.fromName)}:</b> ${formatText(m.text)}<button class="report-message" data-report-party="${escapeHtml(m.id)}" data-target="${escapeHtml(m.from)}">Report</button></div>`).join('')||'<p class="empty small-empty">No party messages yet.</p>';$$('[data-report-party]').forEach(b=>b.onclick=async()=>{await reportSafety('party-message',b.dataset.reportParty,b.dataset.target);await loadParty()});$('#partyReports').innerHTML=(partyCache.reports||[]).map(r=>`<button class="history-item" data-party-report="${escapeHtml(r.id)}"><b>${escapeHtml(r.title)}</b><small>${escapeHtml(r.owner)} · ${escapeHtml(r.mode)}</small></button>`).join('')||'<p class="empty small-empty">No shared reports yet.</p>';$$('[data-party-report]').forEach(b=>b.onclick=()=>{const report=partyCache.reports.find(r=>r.id===b.dataset.partyReport);if(report)renderReport(report)});$('#partyMessages').scrollTop=$('#partyMessages').scrollHeight}
installFriendsUi();
pageTitles.friends=['FRIENDS & PARTY','Friends'];
const baseShowViewWithFriends=showView;
showView=function(view){if(view!=='friends')return baseShowViewWithFriends(view);activeView=view;closeMobileMenu();$$('.side-link').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$$('.view').forEach(x=>x.classList.remove('active'));$('#report').classList.add('hidden');$('#friendsView').classList.add('active');$('#pageKicker').textContent='FRIENDS & PARTY';$('#pageTitle').textContent='Friends';loadFriendsHub();window.scrollTo({top:0,behavior:'smooth'})};
